# Native OOXML export: no Excel installation, JavaScript, browser or external library.
function Convert-DesktopXml($Value){return [Security.SecurityElement]::Escape(([string]$Value -replace '[\x00-\x08\x0b\x0c\x0e-\x1f]',''))}
function Get-DesktopColumn([int]$Index){$s='';while($Index -gt 0){$Index--;$s=[char](65+$Index%26)+$s;$Index=[Math]::Floor($Index/26)};return $s}
function Write-DesktopWorkbook([string]$Path,[string]$Title,$Definitions,$Rows,[string]$LogoPath,[string]$Actor){
 Add-Type -AssemblyName System.IO.Compression;Add-Type -AssemblyName System.IO.Compression.FileSystem
 $temp=$Path+'.'+[Guid]::NewGuid().ToString('N')+'.tmp';$stream=$null;$zip=$null
 try{
  $stream=[IO.File]::Open($temp,[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);$zip=New-Object IO.Compression.ZipArchive($stream,[IO.Compression.ZipArchiveMode]::Create,$true)
  function Add-WorkbookEntry([string]$Name,[string]$Text){$entry=$zip.CreateEntry($Name);$writer=New-Object IO.StreamWriter($entry.Open(),[Text.UTF8Encoding]::new($false));try{$writer.Write($Text)}finally{$writer.Dispose()}}
  $count=$Definitions.Count;$last=Get-DesktopColumn $count;$end=7+$Rows.Count
  $sheet=New-Object Text.StringBuilder
  [void]$sheet.Append('<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetViews><sheetView workbookViewId="0"><pane ySplit="7" topLeftCell="A8" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>')
  for($i=0;$i -lt $count;$i++){[void]$sheet.Append(('<col min="{0}" max="{0}" width="{1}" customWidth="1"/>' -f ($i+1),$Definitions[$i][2]))}
  [void]$sheet.Append('</cols><sheetData><row r="1" ht="24" customHeight="1"><c r="C1" t="inlineStr" s="1"><is><t>CÔNG TY LTD VIỆT NAM</t></is></c></row><row r="2" ht="30" customHeight="1"><c r="C2" t="inlineStr" s="2"><is><t>'+ (Convert-DesktopXml $Title)+'</t></is></c></row><row r="3"><c r="C3" t="inlineStr" s="3"><is><t>'+ (Convert-DesktopXml ('Ngày xuất: '+[DateTime]::Now.ToString('dd/MM/yyyy HH:mm')+' · Người xuất: '+$Actor))+'</t></is></c></row><row r="5"><c r="A5" t="inlineStr" s="1"><is><t>TỔNG BẢN GHI: '+$Rows.Count+'</t></is></c></row><row r="7" ht="32" customHeight="1">')
  for($i=0;$i -lt $count;$i++){[void]$sheet.Append(('<c r="{0}7" t="inlineStr" s="4"><is><t>{1}</t></is></c>' -f (Get-DesktopColumn ($i+1)),(Convert-DesktopXml $Definitions[$i][0])))}
  [void]$sheet.Append('</row>');$rowIndex=8
  foreach($row in $Rows){[void]$sheet.Append(('<row r="{0}" ht="38" customHeight="1">' -f $rowIndex))
   for($i=0;$i -lt $count;$i++){$key=$Definitions[$i][1];$value=$row.$key;$ref=(Get-DesktopColumn ($i+1))+$rowIndex;$style=if($rowIndex%2){6}else{5}
    if($null -ne $value -and ($value -is [int] -or $value -is [long] -or $value -is [double] -or $value -is [decimal]) -and -not [double]::IsNaN([double]$value) -and -not [double]::IsInfinity([double]$value)){
     [void]$sheet.Append(('<c r="{0}" s="{1}"><v>{2}</v></c>' -f $ref,$style,([string]::Format([Globalization.CultureInfo]::InvariantCulture,'{0}',$value))))
    }else{[void]$sheet.Append(('<c r="{0}" t="inlineStr" s="{1}"><is><t xml:space="preserve">{2}</t></is></c>' -f $ref,$style,(Convert-DesktopXml $value)))}
   };[void]$sheet.Append('</row>');$rowIndex++
  }
  [void]$sheet.Append('</sheetData>')
  if($count -ge 4){[void]$sheet.Append('<mergeCells count="3"><mergeCell ref="C1:'+$last+'1"/><mergeCell ref="C2:'+$last+'2"/><mergeCell ref="C3:'+$last+'3"/></mergeCells>')}
  [void]$sheet.Append('<printOptions horizontalCentered="1"/><pageMargins left="0.25" right="0.25" top="0.4" bottom="0.4" header="0.2" footer="0.2"/><pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/><headerFooter><oddFooter>&amp;L LTD VIỆT NAM&amp;R Trang &amp;P / &amp;N</oddFooter></headerFooter>')
  $hasLogo=Test-Path -LiteralPath $LogoPath
  if($hasLogo){[void]$sheet.Append('<drawing r:id="rId2"/>')}
  if($Rows.Count){[void]$sheet.Append('<tableParts count="1"><tablePart r:id="rId1"/></tableParts>')}
  [void]$sheet.Append('</worksheet>');Add-WorkbookEntry 'xl/worksheets/sheet1.xml' $sheet.ToString()
  $styles='<?xml version="1.0" encoding="UTF-8"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="5"><font><sz val="11"/><name val="Calibri"/><color rgb="FF243B4A"/></font><font><b/><sz val="12"/><name val="Calibri"/><color rgb="FF0F6554"/></font><font><b/><sz val="20"/><name val="Calibri"/><color rgb="FF124A40"/></font><font><sz val="10"/><name val="Calibri"/><color rgb="FF728A95"/></font><font><b/><sz val="11"/><name val="Calibri"/><color rgb="FFFFFFFF"/></font></fonts><fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF116551"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF0F6F4"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="2"><border/><border><left style="thin"><color rgb="FFD7E5E0"/></left><right style="thin"><color rgb="FFD7E5E0"/></right><top style="thin"><color rgb="FFD7E5E0"/></top><bottom style="thin"><color rgb="FFD7E5E0"/></bottom></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="7"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0"/><xf numFmtId="0" fontId="2" fillId="0" borderId="0"/><xf numFmtId="0" fontId="3" fillId="0" borderId="0"/><xf numFmtId="0" fontId="4" fillId="2" borderId="1" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="3" borderId="1" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>'
  Add-WorkbookEntry 'xl/styles.xml' $styles
  Add-WorkbookEntry 'xl/workbook.xml' ('<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Báo cáo LTD" sheetId="1" r:id="rId1"/></sheets><definedNames><definedName name="_xlnm.Print_Titles" localSheetId="0">''Báo cáo LTD''!$7:$7</definedName></definedNames></workbook>')
  Add-WorkbookEntry 'xl/_rels/workbook.xml.rels' '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'
  Add-WorkbookEntry '_rels/.rels' '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'
  $rels='<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">';$content='<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
  if($Rows.Count){$table='<table xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" id="1" name="LTDReport" displayName="LTDReport" ref="A7:'+$last+$end+'" totalsRowShown="0"><autoFilter ref="A7:'+$last+$end+'"/><tableColumns count="'+$count+'">';for($i=0;$i -lt $count;$i++){$table+='<tableColumn id="'+($i+1)+'" name="'+(Convert-DesktopXml $Definitions[$i][0])+'"/>'};$table+='</tableColumns><tableStyleInfo name="TableStyleMedium2" showRowStripes="1"/></table>';Add-WorkbookEntry 'xl/tables/table1.xml' $table;$rels+='<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/table" Target="../tables/table1.xml"/>';$content+='<Override PartName="/xl/tables/table1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.table+xml"/>'}
  if($hasLogo){$entry=$zip.CreateEntry('xl/media/logo.jpg');$output=$entry.Open();try{$bytes=[IO.File]::ReadAllBytes($LogoPath);$output.Write($bytes,0,$bytes.Length)}finally{$output.Dispose()};Add-WorkbookEntry 'xl/drawings/drawing1.xml' '<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><xdr:oneCellAnchor><xdr:from><xdr:col>0</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>0</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from><xdr:ext cx="1400000" cy="700000"/><xdr:pic><xdr:nvPicPr><xdr:cNvPr id="1" name="LTD Logo"/><xdr:cNvPicPr/></xdr:nvPicPr><xdr:blipFill><a:blip xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:embed="rId1"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill><xdr:spPr><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic><xdr:clientData/></xdr:oneCellAnchor></xdr:wsDr>';Add-WorkbookEntry 'xl/drawings/_rels/drawing1.xml.rels' '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/logo.jpg"/></Relationships>';$rels+='<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing1.xml"/>';$content+='<Default Extension="jpg" ContentType="image/jpeg"/><Override PartName="/xl/drawings/drawing1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/>'}
  Add-WorkbookEntry 'xl/worksheets/_rels/sheet1.xml.rels' ($rels+'</Relationships>');Add-WorkbookEntry '[Content_Types].xml' ($content+'</Types>')
  $zip.Dispose();$zip=$null;$stream.Dispose();$stream=$null
  if([IO.File]::Exists($Path)){[IO.File]::Replace($temp,$Path,[NullString]::Value)}else{[IO.File]::Move($temp,$Path)}
 }finally{if($zip){$zip.Dispose()};if($stream){$stream.Dispose()};if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Force}}
}
